ReplacementContent:
Widget _buildNavItem(
  int index,
  String title,
  IconData icon,
  bool isSelected,
  bool isCollapsed,
  bool isDrawer, {
  bool hasDot = false,
}) {
  final notifier = ref.read(dcConsoleProvider.notifier);

  return Container(
    margin: const EdgeInsets.only(bottom: 4),
    child: Material(
      color: isSelected ? const Color(0xFF1E254E) : Colors.transparent,
      borderRadius: BorderRadius.circular(10),
      child: InkWell(
        onTap: () {
          notifier.setActiveTab(index);
          if (isDrawer) {
            Navigator.of(context).pop();
          }
        },
        borderRadius: BorderRadius.circular(10),
        hoverColor: Colors.white.withValues(alpha: 0.08),
        child: Stack(
          alignment: Alignment.centerLeft,
          children: [
            if (isSelected)
              Positioned(
                left: 0,
                top: 6,
                bottom: 6,
                child: Container(
                  width: 4,
                  decoration: BoxDecoration(
                    color: const Color(0xFF6366F1),
                    borderRadius: BorderRadius.circular(4),
                  ),
                ),
              ),
            Padding(
              padding: EdgeInsets.symmetric(
                horizontal: isCollapsed ? 12 : 14,
                vertical: 11,
              ),
              child: Row(
                mainAxisAlignment: isCollapsed ? MainAxisAlignment.center : MainAxisAlignment.start,
                children: [
                  if (!isCollapsed && isSelected) const SizedBox(width: 4),
                  Icon(
                    icon,
                    size: 20,
                    color: isSelected ? const Color(0xFF818CF8) : const Color(0xFF8293B5),
                  ),
                  if (!isCollapsed) ...[
                    const SizedBox(width: 12),
                    Expanded(
                      child: Text(
                        title,
                        style: GoogleFonts.inter(
                          fontSize: 13,
                          fontWeight: isSelected ? FontWeight.bold : FontWeight.w500,
                          color: isSelected ? Colors.white : const Color(0xFFCBD5E1),
                        ),
                        overflow: TextOverflow.ellipsis,
                      ),
                    ),
                    if (isSelected || hasDot)
                      Container(
                        width: 22,
                        height: 22,
                        decoration: BoxDecoration(
                          color: const Color(0xFF2E2938),
                          shape: BoxShape.circle,
                          border: Border.all(
                            color: const Color(0xFFF59E0B).withValues(alpha: 0.25),
                            width: 1.5,
                          ),
                        ),
                        child: Center(
                          child: Container(
                            width: 9,
                            height: 9,
                            decoration: const BoxDecoration(
                              color: Color(0xFFF59E0B),
                              shape: BoxShape.circle,
                            ),
                          ),
                        ),
                      ),
                  ],
                ],
              ),
            ),
          ],
        ),
      ),
    ),
  );
}

